    stack = [spec["start"]]
    while stack:
        n = stack.pop()
        if n in any_seen:
            continue
        any_seen.add(n)
        if n in road_adj:
            stack.extend(road_adj[n])
        if n in rail_adj:
            stack.extend(rail_adj[n])
    road_seen = set()
    stack = [spec["start"]]
    while stack:
        n = stack.pop()
        if n in road_seen:
