def main():
    # Weighted DAG: adjacency mapping node -> list of (neighbor, weight)
    adj = {
        "A": [("B", 3), ("C", 2)],
        "B": [("D", 4)],
        "C": [("D", 1), ("E", 5)],
        "D": [("E", 2)],
        "E": [],
    }

    memo = {}

    def longest_from(n):
        if n in memo:
            return memo[n]
        best = 0
        for nb, w in adj[n]:
            best = max(best, w + longest_from(nb))
        memo[n] = best
        return best

    answer = max(longest_from(n) for n in adj)
    print(f"longest weighted path = {answer}")


if __name__ == "__main__":
    main()
```

