def strong_or_rail_reach(spec: dict) -> int:
    """Count nodes reachable crossing roads of weight >= min_w or any rail edge."""
    adj = {}
    for trip in spec["roads"]:
        if trip[2] >= spec["min_w"]:
            if trip[0] not in adj:
                adj[trip[0]] = []
            adj[trip[0]].append(trip[1])
    for pair in spec["rails"]:
        if pair[0] not in adj:
            adj[pair[0]] = []
        adj[pair[0]].append(pair[1])
    seen = set()
    stack = [spec["start"]]
    while stack:
        n = stack.pop()
        if n in seen:
            continue
        seen.add(n)
        if n in adj:
            stack.extend(adj[n])
    return len(seen)
```

