def unblocked_follower_count(spec: dict) -> int:
    """Count users reachable via follow edges (excluding start) not directly blocked by start."""
    adj = {}
    for pair in spec["follows"]:
        if pair[0] not in adj:
            adj[pair[0]] = []
        adj[pair[0]].append(pair[1])
    seen = set()
    stack = [spec["start"]]
    while stack:
        n = stack.pop()
        if n in seen:
            continue
        seen.add(n)
        if n in adj:
            stack.extend(adj[n])
    blocked = []
    for pair in spec["blocks"]:
        if pair[0] == spec["start"]:
            blocked.append(pair[1])
    count = 0
    for n in seen:
        if n != spec["start"] and n not in blocked:
            count += 1
    return count
