    def eft(n):
        if n in memo:
            return memo[n]
        best = 0
        for (p, w) in preds[n]:
            best = max(best, eft(p) + w)
        memo[n] = best
        return best

    answer = max(eft(n) for n in nodes)
    print(f"critical path length = {answer}")


if __name__ == "__main__":
