def same_component(spec: dict) -> bool:
    """True when u and v lie in the same undirected component."""
    adj = {n: [] for n in spec["nodes"]}
    for a, b in spec["links"]:
        adj[a].append(b)
        adj[b].append(a)
    u = spec["u"]; v = spec["v"]
    seen = set(); stack = [u]
    while stack:
        n = stack.pop()
        if n in seen:
            continue
        seen.add(n)
        if n == v:
            return True
        stack.extend(adj[n])
    return False
