def shared_reach_count(spec: dict) -> int:
    """Count nodes reachable from start by road-only AND by rail-only traversal."""
    road_adj = {}
    for pair in spec["roads"]:
        if pair[0] not in road_adj:
            road_adj[pair[0]] = []
        road_adj[pair[0]].append(pair[1])
    rail_adj = {}
    for pair in spec["rails"]:
        if pair[0] not in rail_adj:
            rail_adj[pair[0]] = []
        rail_adj[pair[0]].append(pair[1])
    road_seen = set()
    stack = [spec["start"]]
    while stack:
        n = stack.pop()
        if n in road_seen:
            continue
        road_seen.add(n)
        if n in road_adj:
            stack.extend(road_adj[n])
    rail_seen = set()
    stack = [spec["start"]]
    while stack:
        n = stack.pop()
        if n in rail_seen:
            continue
        rail_seen.add(n)
        if n in rail_adj:
            stack.extend(rail_adj[n])
    both = 0
    for n in road_seen:
        if n in rail_seen:
            both += 1
    return both
