def sorted_road_lengths(spec: dict) -> list:
    """Collect the length of every road leaving a reachable junction, sorted."""
    adj = {}
    for s, t, w in spec["edges"]:
        adj.setdefault(s, []).append((t, w))
    seen = set()
    stack = [spec["start"]]
    found = []
    while stack:
        n = stack.pop()
        if n in seen:
            continue
        seen.add(n)
        for t, w in adj.get(n, []):
            found.append(w)
            stack.append(t)
    return sorted(found)
