from collections import deque


def main():
    # Undirected graph as dict-of-lists adjacency
    adj = {
        "A": ["B", "C"],
        "B": ["A", "D"],
        "C": ["A", "D", "E"],
        "D": ["B", "C", "E"],
        "E": ["C", "D"],
    }
    start, goal = "A", "E"

    visited = {start}
    pred = {}
    q = deque([start])
    while q:
        cur = q.popleft()
        if cur == goal:
            break
        for nb in adj[cur]:
            if nb not in visited:
                visited.add(nb)
                pred[nb] = cur
                q.append(nb)

    path = [goal]
    while path[-1] != start:
        path.append(pred[path[-1]])
    path.reverse()

    print(f"{path} ({len(path) - 1} hops)")


if __name__ == "__main__":
    main()
