def wider_network(spec: dict) -> str:
    """Return which edge type reaches more nodes from start: road, rail, or tie."""
    road_adj = {}
    for pair in spec["roads"]:
        if pair[0] not in road_adj:
            road_adj[pair[0]] = []
        road_adj[pair[0]].append(pair[1])
    rail_adj = {}
    for pair in spec["rails"]:
        if pair[0] not in rail_adj:
            rail_adj[pair[0]] = []
        rail_adj[pair[0]].append(pair[1])
    road_seen = set()
    stack = [spec["start"]]
    while stack:
        n = stack.pop()
        if n in road_seen:
            continue
        road_seen.add(n)
        if n in road_adj:
            stack.extend(road_adj[n])
    rail_seen = set()
    stack = [spec["start"]]
    while stack:
        n = stack.pop()
        if n in rail_seen:
            continue
        rail_seen.add(n)
        if n in rail_adj:
            stack.extend(rail_adj[n])
    if len(road_seen) > len(rail_seen):
        return "road"
    if len(rail_seen) > len(road_seen):
        return "rail"
    return "tie"
```

