def merge_sort(arr: Any) -> object {
    if (len(arr) <= 1) {
        return arr;
    }
    mid = len(arr) // 2;
    left = arr[:mid];
    right = arr[mid:];
    merge_sort(left);
    merge_sort(right);
    merge(arr, left, right);
}



