def count_max_occurrences(spec: dict) -> int:
    """How many chain values equal the chain maximum."""
    nums = spec["nums"]
    if not nums:
        return 0
    peak = nums[0]
    for n in nums:
        if n > peak:
            peak = n
    hits = 0
    for n in nums:
        if n == peak:
            hits += 1
    return hits
